UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","timeUsed"}', '["Busan Station pickup (~08:10, ~5 min)","Drive to Seomyeon Station (~15 min)","Seomyeon pickup (~08:30, ~5 min)","Drive to Haeundae Station (~35 min)","Haeundae pickup (~09:10, ~5 min)"]'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'en'
  AND detail_payload #> '{"itineraryStops","0","timeUsed"}' = '["Busan Station pickup (~09:00, ~5 min)","Drive to Seomyeon Station (~10 min)","Seomyeon pickup (~09:15, ~5 min)","Drive to Haeundae Station (~15 min)","Haeundae pickup (~09:30, ~5 min)"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"Three pickup points cover Busan''s three main hotel zones (KTX/Nampo, Seomyeon mid-city, Haeundae beachfront) without forcing guests to transit across the city in the morning. Sequencing west→east minimizes coach distance and lands the group at Haedong Yonggungsa around 09:50 — early enough to beat the busiest tour-bus arrivals."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'en'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'Three pickup points cover Busan''s three main hotel zones (KTX/Nampo, Seomyeon mid-city, Haeundae beachfront) without forcing guests to transit across the city in the morning. Sequencing northwest→east minimizes coach distance and lands the group at Haedong Yonggungsa around 10:00 — early enough to beat the busiest tour-bus arrivals.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"Pickup is consolidated at three central Busan transit hubs to keep the day manageable without crisscrossing the city: **Busan Station (Line 1)** for guests staying near the KTX terminal or in the Choryang/Nampo-dong area; **Seomyeon Station (Lines 1 & 2)** — Busan''s busiest subway interchange, central for guests in mid-city hotels around Lotte Hotel Busan or the Seomyeon Medical Street; and **Haeundae Station (Line 2)** for guests in the beachfront resort district near Westin Josun, Park Hyatt, or Signiel Busan. \n\nThe coach picks up at all three in sequence (Busan Station Exit 4 at 08:10, Seomyeon Station Exit 4 at 08:30, Haeundae Station Exit 5 at 09:10) and then heads northeast along the coastal Gwangan Bridge route toward Gijang-gun for the day''s first stop. \n\nTotal transit from final pickup to Haedong Yonggungsa: ~30-40 minutes depending on traffic. Driver will share a printed Korean-English itinerary card with timings; please be at your pickup point 5 minutes before the scheduled time to keep the day on track for the later UN Memorial Cemetery and Gamcheon stops, which have stricter operating windows."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'en'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'Pickup is consolidated at three central Busan transit hubs to keep the day manageable without crisscrossing the city: **Busan Station (Line 1)** for guests staying near the KTX terminal or in the Choryang/Nampo-dong area; **Seomyeon Station (Lines 1 & 2)** — Busan''s busiest subway interchange, central for guests in mid-city hotels around Lotte Hotel Busan or the Seomyeon Medical Street; and **Haeundae Station (Line 2)** for guests in the beachfront resort district near Westin Josun, Park Hyatt, or Signiel Busan. 

The coach picks up at all three in sequence (typically Busan Station first ~09:00, Seomyeon ~09:15, Haeundae ~09:30) and then heads northeast along the coastal Gwangan Bridge route toward Gijang-gun for the day''s first stop. 

Total transit from final pickup to Haedong Yonggungsa: ~30-40 minutes depending on traffic. Driver will share a printed Korean-English itinerary card with timings; please be at your pickup point 5 minutes before the scheduled time to keep the day on track for the later UN Memorial Cemetery and Gamcheon stops, which have stricter operating windows.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","routeLogicSections","1","items","2","detail"}', '"Pickup at Busan Station, Seomyeon, or Haeundae — accessible from most central-Busan accommodations. Choose the exit closest to your hotel; your effective tour length varies by about 15 minutes depending on which one you pick."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'en'
  AND detail_payload #>> '{"whyTourWorks","routeLogicSections","1","items","2","detail"}' = 'Pickup at Seomyeon, Busan Station, or Haeundae — accessible from most central-Busan accommodations. Choose the exit closest to your hotel; tour duration adjusts ±30 min based on pickup point.';

