UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"pickup_dropoff"}', '{"departure":[{"order":1,"time":"08:10","name":"Busan Station Exit 4 (not the KTX gate)","type":"station","lat":35.11449,"lng":129.03933},{"order":2,"time":"08:30","name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":3,"time":"09:10","name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"return":[{"order":1,"name":"Nampo-dong / Jagalchi area","type":"station","lat":35.09663,"lng":129.0308},{"order":2,"name":"Busan Station (Exit 4)","type":"station","lat":35.11449,"lng":129.03933},{"order":3,"name":"Seomyeon Station (Exit 4)","type":"station","lat":35.15782,"lng":129.06003},{"order":4,"name":"Haeundae Station (Exit 5)","type":"station","lat":35.16396,"lng":129.15853}],"notes":["Choose the pickup exit closest to your hotel at booking. Drop-offs are sequential along the return route; passengers boarding at Busan Station (08:10) or Seomyeon (08:30) have the longest day (≈10 hours), Haeundae passengers the shortest (just under 10 hours)."]}'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'en'
