  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'Los tres puntos de recogida cubren las tres principales zonas hoteleras de Busan (KTX/Nampo, Seomyeon centro, playa de Haeundae) sin obligar a los huéspedes a cruzar la ciudad por la mañana. La secuencia noroeste→este minimiza la distancia del autobús y lleva al grupo a Haedong Yonggungsa hacia las 10:00, con tiempo suficiente para adelantarse a la llegada de los autobuses turísticos más concurridos.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"La recogida está centralizada en tres nodos de transporte del centro de Busan para facilitar el día sin tener que cruzar la ciudad de un extremo a otro: **Estación de Busan (Línea 1)** para los huéspedes alojados cerca de la terminal KTX o en la zona de Choryang/Nampo-dong; **Estación de Seomyeon (Líneas 1 y 2)** — el intercambiador de metro más transitado de Busan, céntrico para los huéspedes en hoteles del centro como el Lotte Hotel Busan o la calle médica de Seomyeon; y **Estación de Haeundae (Línea 2)** para los huéspedes en el distrito turístico frente al mar cerca del Westin Josun, Park Hyatt o Signiel Busan. \n\nEl autobús recoge en los tres puntos en secuencia (Estación de Busan Salida 4 a las 08:10, Estación Seomyeon Salida 4 a las 08:30, Estación Haeundae Salida 5 a las 09:10) y luego se dirige al noreste por la ruta costera del Puente Gwangan hacia Gijang-gun para la primera parada del día. Tiempo total de tránsito desde la última recogida hasta Haedong Yonggungsa: ~30-40 minutos según el tráfico. \n\nEl conductor repartirá una tarjeta impresa con el itinerario en coreano e inglés con los horarios; por favor, esté en su punto de recogida 5 minutos antes de la hora programada para mantener el ritmo del día, especialmente en las paradas posteriores del Cementerio Memorial de la ONU y Gamcheon, que tienen horarios de funcionamiento más estrictos."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'es'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'La recogida está centralizada en tres nodos de transporte del centro de Busan para facilitar el día sin tener que cruzar la ciudad de un extremo a otro: **Estación de Busan (Línea 1)** para los huéspedes alojados cerca de la terminal KTX o en la zona de Choryang/Nampo-dong; **Estación de Seomyeon (Líneas 1 y 2)** — el intercambiador de metro más transitado de Busan, céntrico para los huéspedes en hoteles del centro como el Lotte Hotel Busan o la calle médica de Seomyeon; y **Estación de Haeundae (Línea 2)** para los huéspedes en el distrito turístico frente al mar cerca del Westin Josun, Park Hyatt o Signiel Busan. 

El autobús recoge en los tres puntos en secuencia (generalmente Estación de Busan primero ~09:00, Seomyeon ~09:15, Haeundae ~09:30) y luego se dirige al noreste por la ruta costera del Puente Gwangan hacia Gijang-gun para la primera parada del día. Tiempo total de tránsito desde la última recogida hasta Haedong Yonggungsa: ~30-40 minutos según el tráfico. 

El conductor repartirá una tarjeta impresa con el itinerario en coreano e inglés con los horarios; por favor, esté en su punto de recogida 5 minutos antes de la hora programada para mantener el ritmo del día, especialmente en las paradas posteriores del Cementerio Memorial de la ONU y Gamcheon, que tienen horarios de funcionamiento más estrictos.';

