UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"三个接送地点覆盖釜山三大主要酒店区（KTX/南浦洞、西面市中心、海云台海滨），无需宾客早晨跨城出行。自西向东的接送顺序使包车行驶距离最短，并于约09:50抵达海东龙宫寺——早于旅游大巴最拥挤的时段，抢先入场。"'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'zh'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = '三个接送地点覆盖釜山三大主要酒店区（KTX/南浦洞、西面市中心、海云台海滨），无需宾客早晨跨城出行。从西北向东的接送顺序使包车行驶距离最短，并于约10:00抵达海东龙宫寺——早于旅游大巴最拥挤的时段，抢先入场。';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"接送地点设于釜山市中心三个主要交通枢纽，方便行程安排，无需在城市间来回奔波：**釜山站（地铁1号线）** 适合住在KTX终点站附近或草梁洞/南浦洞一带的宾客；**西面站（地铁1、2号线）** — 釜山最繁忙的地铁换乘站，适合住在乐天酒店釜山或西面医疗街一带市中心酒店的宾客；**海云台站（地铁2号线）** 适合住在海滨度假区、威斯汀朝鲜酒店、柏悦酒店或信义釜山酒店附近的宾客。\n\n大巴按顺序依次接送（釜山站4号出口08:10、西面站4号出口08:30、海云台站5号出口09:10），随后沿海岸广安大桥路线向东北方向前往机张郡，开始当天的第一站。从最后一个接送点到海东龙宫寺的总行程时间：约30-40分钟（视路况而定）。司机将发放中韩双语行程时刻卡；请在预定时间前5分钟到达接送地点，以确保行程顺利推进，不耽误后续联合国纪念公园和甘川洞等开放时间较严格的景点。"'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'zh'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = '接送地点设于釜山市中心三个主要交通枢纽，方便行程安排，无需在城市间来回奔波：**釜山站（地铁1号线）** 适合住在KTX终点站附近或草梁洞/南浦洞一带的宾客；**西面站（地铁1、2号线）** — 釜山最繁忙的地铁换乘站，适合住在乐天酒店釜山或西面医疗街一带市中心酒店的宾客；**海云台站（地铁2号线）** 适合住在海滨度假区、威斯汀朝鲜酒店、柏悦酒店或信义釜山酒店附近的宾客。

大巴按顺序依次接送（通常釜山站最先约09:00，西面约09:15，海云台约09:30），随后沿海岸广安大桥路线向东北方向前往机张郡，开始当天的第一站。从最后一个接送点到海东龙宫寺的总行程时间：约30-40分钟（视路况而定）。司机将发放中韩双语行程时刻卡；请在预定时间前5分钟到达接送地点，以确保行程顺利推进，不耽误后续联合国纪念公园和甘川洞等开放时间较严格的景点。';

