UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"三個接送地點涵蓋釜山三大主要住宿區域（KTX／南浦洞、西面市中心、海雲台海濱），無需旅客在清晨橫越城市。由西向東的接送順序可縮短旅遊車行駛距離，並讓團體在約 09:50 抵達海東龍宮寺——足以趕在旅遊巴士最繁忙的時段之前。"'::jsonb, false),
